public int getMinimumCost(int k, int[] c) {
    int[] best = { Integer.MAX_VALUE };
    permute(c, 0, k, best);
    return best[0];
}

private void permute(int[] c, int start, int k, int[] best) {
    if (start == c.length) {
        int total = 0;
        for (int i = 0; i < c.length; i++) {
            total += (i / k + 1) * c[i];
        }
        best[0] = Math.min(best[0], total);
        return;
    }
    for (int i = start; i < c.length; i++) {
        int t = c[start]; c[start] = c[i]; c[i] = t;
        permute(c, start + 1, k, best);
        t = c[start]; c[start] = c[i]; c[i] = t;
    }
}

