from itertools import permutations

def getMinimumCost(k: int, c: list[int]) -> int:
    best = float("inf")
    for order in permutations(c):
        total = sum((i // k + 1) * cost for i, cost in enumerate(order))
        best = min(best, total)
    return int(best)

