public int getMinimumCost(int k, int[] c) {
    Integer[] flowers = new Integer[c.length];
    for (int i = 0; i < c.length; i++) {
        flowers[i] = c[i];
    }
    Arrays.sort(flowers, Comparator.reverseOrder());
    int total = 0;
    for (int i = 0; i < flowers.length; i++) {
        int multiplier = i / k + 1;
        total += multiplier * flowers[i];
    }
    return total;
}

